// halo3 - the run-time shader translator (see halo3_traductor.h).
//
// XenosRecomp is built into this one file with the defines of its GLSL mode: the translator's class layout depends on
// them, so nothing else includes shader_recompiler.h.
#define NFSMW_RECOMP 1
#define HALO3_RECOMP 1
#define XENOS_GLSL 1
#include "../../shaders/pch_min.h"
#include "../../shaders/XenosRecomp/shader_recompiler.cpp"

#include "halo3_traductor.h"
#include "halo3_traductor_nucleo.h"

#include "halo3_preludio_glsl.h"  // generated by CMake from shaders/XenosRecomp/shader_common.glsl: kPreludioGlsl

#include <rex/cvar.h>
#include <rex/filesystem.h>
#include <rex/ui/deko3d/glsl.h>

#include <cstdio>
#include <exception>
#include <filesystem>
#include <string>
#include <string_view>

REXCVAR_DEFINE_BOOL(halo3_volcar_shaders, false, "Halo3",
                    "Diagnostic: write each translated shader (GLSL and raw microcode) to shaders_glsl/ beside the NRO, "
                    "named by the number the draw lists show")
    .lifecycle(rex::cvar::Lifecycle::kInitOnly);
REXCVAR_DEFINE_STRING(halo3_volcar_numeros, "", "Halo3",
                      "Diagnostic: with halo3_volcar_shaders, only these shaders (comma-separated numbers as the draw "
                      "lists show them, e.g. 2147483697); empty writes every one")
    .lifecycle(rex::cvar::Lifecycle::kInitOnly);
REXCVAR_DEFINE_BOOL(halo3_bucles_estructurados, false, "Halo3",
                    "Testing: loops with jumps translated as structured loops instead of the general form (faster on "
                    "the GPU; the first build with it hit a GPU fault)")
    .lifecycle(rex::cvar::Lifecycle::kInitOnly);

namespace halo3 {

void VolcarShader(bool vertices, uint32_t numero, std::span<const uint32_t> microcodigo, const std::string& glsl) {
  static const bool volcar = REXCVAR_GET(halo3_volcar_shaders);
  if (!volcar) return;
  static const std::string numeros = "," + std::string(REXCVAR_GET(halo3_volcar_numeros)) + ",";
  if (numeros != ",," && numeros.find(fmt::format(",{},", numero)) == std::string::npos) return;
  const std::filesystem::path carpeta = rex::filesystem::GetExecutableFolder() / "shaders_glsl";
  std::error_code ec;
  std::filesystem::create_directories(carpeta, ec);
  const std::string base = (carpeta / fmt::format("{}_{}", vertices ? "v" : "p", numero)).string();
  if (FILE* f = std::fopen((base + ".glsl").c_str(), "wb")) {
    std::fwrite(glsl.data(), 1, glsl.size(), f);
    std::fclose(f);
  }
  if (FILE* f = std::fopen((base + ".bin").c_str(), "wb")) {
    std::fwrite(microcodigo.data(), 4, microcodigo.size(), f);
    std::fclose(f);
  }
}

uint32_t HuellaPreludio() {
  const uint64_t h = XXH3_64bits(kPreludioGlsl, sizeof(kPreludioGlsl) - 1);
  return uint32_t(h ^ (h >> 32)) | 1u;  // never 0, which means no stamp
}

bool TraducirMicrocodigo(bool vertices, std::span<const uint32_t> microcodigo, uint32_t interpoladores,
                         uint32_t posicion_pixel, rex::x360::EntradaShader& e, std::string& error) {
  if (microcodigo.empty() || microcodigo.size() > 0x10000) {
    error = "microcodigo vacio o demasiado largo";
    return false;
  }
  std::string texto;
  uint32_t salidas = 0;
  try {
    static const bool bucles = REXCVAR_GET(halo3_bucles_estructurados);
    texto = nucleo::Traducir(vertices, microcodigo, kPreludioGlsl, salidas, interpoladores, bucles, posicion_pixel);
  } catch (const std::exception& excepcion) {
    error = excepcion.what();
    return false;
  }
  const std::string_view cuerpo = nucleo::Cuerpo(texto);
  // Diagnostic: the exporting shaders too large for the export code (nucleo::kPalabrasMaxExportacion), their microcode
  // to logs/rex once, to reproduce uam's trouble with them on the PC.
  if (vertices && microcodigo.size() > nucleo::kPalabrasMaxExportacion) {
    const uint64_t huella = XXH3_64bits(microcodigo.data(), microcodigo.size_bytes());
    const std::filesystem::path ruta =
        rex::filesystem::GetExecutableFolder() / "logs" / "rex" / fmt::format("exporta_grande_{:016X}.bin", huella);
    std::error_code ec;
    if (!std::filesystem::exists(ruta, ec)) {
      if (FILE* f = std::fopen(ruta.string().c_str(), "wb")) {
        std::fwrite(microcodigo.data(), 4, microcodigo.size(), f);
        std::fclose(f);
      }
    }
  }
  if (cuerpo.empty()) {
    error = "la traduccion no tiene main";
    return false;
  }
  // Diagnostic: a shader that exports to memory loses those writes here (shader_recompiler.cpp marks them). Its
  // results then never reach what reads them: the frame's exposure, say.
  if (const size_t m = cuerpo.find("MEMEXPORT"); m != std::string_view::npos) {
    static uint32_t avisados = 0;
    if (avisados < 40) {
      ++avisados;
      size_t n = 0;
      for (size_t p = m; p != std::string_view::npos; p = cuerpo.find("MEMEXPORT", p + 1)) {
        ++n;
      }
      std::fprintf(stderr, "[halo3] %s shader con exportacion a memoria: %zu escrituras perdidas, %zu palabras, huella %016llX\n",
                   vertices ? "vertex" : "pixel", n, microcodigo.size(),
                   (unsigned long long)XXH3_64bits(microcodigo.data(), microcodigo.size_bytes()));
    }
  }

  const rex::deko3d::GlslDeko g = rex::deko3d::GlslDeTraductor(texto, vertices, 0);
  if (!g.error.empty()) {
    error = g.error;
    return false;
  }
  e.vertices = vertices;
  e.microcodigo.assign(microcodigo.begin(), microcodigo.end());
  e.huella = XXH3_64bits(microcodigo.data(), microcodigo.size_bytes());
  e.huella_contenedor = 0;
  e.elementos.clear();
  e.samplers.clear();
  for (uint32_t b = 0; b < rex::deko3d::kMaxTexturas; ++b) {
    if (!((g.texturas >> b) & 1)) continue;
    rex::x360::SamplerShader s;
    s.registro = uint16_t(b);
    s.tipo = ((g.texturas_3d >> b) & 1) ? 13 : ((g.texturas_cubo >> b) & 1) ? 14 : 12;  // D3DXPARAMETER_TYPE
    e.samplers.push_back(s);
  }
  e.salidas = salidas;
  // Only the shader's own kills: every translated pixel shader ends with the alpha test's clip, which the
  // specialization removes when the test is off (the renderer checks RB_COLORCONTROL for it). Counted as a discard,
  // it kept the pixel shader on every depth-only draw and late depth on every draw.
  e.descarta = cuerpo.find("discard") != std::string_view::npos;
  for (size_t p = cuerpo.find("clip("); p != std::string_view::npos && !e.descarta; p = cuerpo.find("clip(", p + 1)) {
    const std::string_view resto = cuerpo.substr(p + 5);
    e.descarta = !resto.starts_with("alphaTestValue(") && !resto.starts_with("oC0.w - g_AlphaThreshold");
  }
  e.constantes_bytes = 256 * 16;
  e.ubicaciones_por_orden = true;
  e.glsl = std::move(texto);
  return true;
}

}  // namespace halo3
